			$('.gnb').animate({left: '-300px'});
		});
		/* DEPTH */
		if(depth>0){
			$(".lnb > ul > li:eq("+(depth-1)+")").addClass('on');
		};
		/* SLIDE */
		$('.slide').bxSlider({
			mode: 'horizontal',
			speed: 1500,
